/**
 * pep8 -> pycodestyle (Python).
 *
 * Why this pair: pep8 was renamed to pycodestyle, so "just change the import" looks safe. It is not:
 * pycodestyle has added checks since (E741, E722, W605, E305 and more), so the same source gets new
 * warnings and a lint step that was green starts failing. The séance generates Python source from a
 * pool of style problems and shows exactly which codes are new. The generated replacement keeps the
 * old results by ignoring the new codes; delete that line when you want the new checks.
 */

import type { KnownDifference, SeanceBundle, SeanceFile } from '../../types.js';
import { renderReadme } from '../readme.js';
import { makeBundle, type Mutant, type Recipe, type RecipeContext } from '../recipe.js';
import { depOfContext, oldVersionsFor } from '../versions.js';

const DIR = 'seance/pep8';

export const PEP8_NEW_CODES = [
  'E204',
  'E252',
  'E275',
  'E305',
  'E306',
  'E722',
  'E741',
  'E742',
  'E743',
  'W504',
  'W505',
  'W605',
];

export const PEP8_KNOWN: KnownDifference[] = [
  {
    input: 'l = 1',
    old: 'no warning',
    naive: 'E741 ambiguous variable name',
    handled:
      'Hidden by default: the replacement drops E741, so the lint result is unchanged. Remove it from NEW_CODES to adopt the check.',
  },
  {
    input: 'try:\\n    pass\\nexcept:\\n    pass',
    old: 'no warning',
    naive: 'E722 do not use bare except',
    handled: 'Hidden by default (NEW_CODES).',
  },
  {
    input: 'a = "\\\\d"',
    old: 'no warning',
    naive: 'W605 invalid escape sequence',
    handled: 'Hidden by default (NEW_CODES).',
  },
  {
    input: 'def f():\\n    pass\\nx = 1',
    old: 'no warning',
    naive: 'E305 expected 2 blank lines after a function',
    handled: 'Hidden by default (NEW_CODES).',
  },
  {
    input: 'd.has_key(1)',
    old: 'W601 .has_key() is deprecated',
    naive: 'no warning (the Python 2 checks W601 to W604 were removed)',
    handled:
      'Accepted: Python 2 checks are gone. The séance does not generate Python 2 constructs.',
  },
  {
    input: 'type(a) == type(b); a comment, a blank line, then def; an import after an if',
    old: 'no E721; E302 expected 2 blank lines; E402 not raised',
    naive: 'E721 reported; no E302; E402 reported',
    handled:
      'Not hidden and not reproduced: E301 to E304, E402 and E721 exist in both but fire on different patterns. The séance leaves them out of its comparisons; review them by hand.',
  },
  {
    input: 'async def k(): ...',
    old: 'treated as an ordinary line: no blank-line checks (E301 to E305)',
    naive: 'the blank-line checks apply (E302 and others)',
    handled:
      'Accepted: pep8 predates async syntax; the new answers are correct. The séance does not generate async code.',
  },
  {
    input: 'the default ignore list',
    old: 'E121, E123, E126, E226, E24, E704',
    naive: 'also W503 and W504',
    handled: 'Reproduced: the replacement starts from the pep8 default list when you pass none.',
  },
];

const REPLACEMENT = String.raw`"""Replacement for pep8. Generated by Necromancer (recipe "pep8").

pep8 was renamed to pycodestyle. This module keeps the results of pep8 1.7.1 by dropping the
checks that pycodestyle added later. To adopt the new checks, shorten NEW_CODES.

Use StyleGuide and Checker where you used pep8.StyleGuide and pep8.Checker.
"""
import pycodestyle

# The default ignore list of pep8 1.7.1 (pycodestyle also ignores W503 and W504 by default).
PEP8_DEFAULT_IGNORE = ("E121", "E123", "E126", "E226", "E24", "E704")

# Checks that pycodestyle added after pep8 1.7.1. Remove a code from this list to start using it.
NEW_CODES = (__NEW_CODES__)

Checker = pycodestyle.Checker
BaseReport = pycodestyle.BaseReport
StandardReport = pycodestyle.StandardReport


def _without_new_codes(base):
    class Report(base):
        def error(self, line_number, offset, text, check):
            if text[:4] in NEW_CODES:
                return None
            return super().error(line_number, offset, text, check)

    return Report


def StyleGuide(*args, **kwargs):
    # With no ignore and no select, pep8 ignored its own default list (pycodestyle's is longer).
    if kwargs.get("ignore") is None and not kwargs.get("select"):
        kwargs["ignore"] = PEP8_DEFAULT_IGNORE
    reporter = kwargs.get("reporter") or (pycodestyle.BaseReport if kwargs.get("quiet") else pycodestyle.StandardReport)
    kwargs["reporter"] = _without_new_codes(reporter)
    return pycodestyle.StyleGuide(*args, **kwargs)
`;

const TEST = String.raw`"""Seance: pep8 -> pycodestyle. Generated by Necromancer (recipe "pep8").

Run: pytest seance/pep8

Generates Python source from a pool of style problems, checks it with pep8 and with the
replacement (the same options for both), and fails on any difference in the reports. Compared: the
sorted list of (line, column, code) and, for check_files, the error counters. The codes in CHANGED (E301 to E304, E402, E721) are left out of both sides (see below).
"""
import os
import tempfile
import warnings

import pytest
from hypothesis import HealthCheck, given, settings
from hypothesis import strategies as st

warnings.simplefilter("ignore")
import pep8  # noqa: E402
import pycodestyle  # noqa: E402
import pep8_replacement  # noqa: E402

SLOW = dict(deadline=None, suppress_health_check=[HealthCheck.too_slow, HealthCheck.data_too_large])


# These codes exist in both, but pycodestyle fires on different patterns: E721 flags type(a) ==
# type(b), the blank-line rules E301 to E304 treat comments and decorators differently, and E402
# allows more statements before an import. They are left out of every comparison below and pinned
# in test_changed_codes_fire_on_different_patterns. Review them by hand when you migrate.
CHANGED = {"E301", "E302", "E303", "E304", "E402", "E721"}


def collector(base):
    class Collect(base):
        def __init__(self, options):
            super().__init__(options)
            self.found = []

        def error(self, line_number, offset, text, check):
            code = super().error(line_number, offset, text, check)
            if code:
                self.found.append((line_number, offset + 1, code))
            return code

    return Collect


def report(guide_factory, base, lines, **options):
    guide = guide_factory(reporter=collector(base), quiet=True, config_file=False, **options)
    checker = (pep8 if guide_factory is pep8.StyleGuide else pep8_replacement).Checker(
        filename="x.py", lines=lines, options=guide.options
    )
    checker.check_all()
    return sorted(f for f in guide.options.report.found if f[2] not in CHANGED)


def old_report(lines, **options):
    return report(pep8.StyleGuide, pep8.BaseReport, lines, **options)


def new_report(lines, **options):
    return report(pep8_replacement.StyleGuide, pycodestyle.BaseReport, lines, **options)


def naive_report(lines, **options):
    guide = pycodestyle.StyleGuide(reporter=collector(pycodestyle.BaseReport), quiet=True, config_file=False, **options)
    pycodestyle.Checker(filename="x.py", lines=lines, options=guide.options).check_all()
    return sorted(f for f in guide.options.report.found if f[2] not in CHANGED)


# Source fragments, valid Python 3, most with a style problem. Python 2 constructs and async are left out.
POOL = [
    "import os, sys\n", "import os\n", "x=1\n", "x = 1 \n", "def f( a ):\n    return a\n",
    "def g(a, b = 1):\n    return a\n", "class A:\n    def f(self): pass\n", "if x == None:\n    pass\n",
    "if not x in y:\n    pass\n", "l = 1\n", "O = 2\n", "a = \"\\d\"\n", "try:\n    pass\nexcept:\n    pass\n",
    "f = lambda: 0\n", "print(a , b)\n", "d = {'a':1}\n", "x = (1,\n  2)\n", "x = 1;\n", "if True: pass\n",
    "y = x if x else None  # c\n", "z = [1,2,3]\n", "def h():\n  pass\n", "w = a<b\n", "s = 'a' 'b'\n",
    "def m(a: int=1) -> int:\n    return a\n", "type(a) == type(b)\n",
    "# comment\n", "#bad comment\n", "x = 1  #bad inline\n", "x = 'a'  # fine\n",
    "x = '" + "a" * 90 + "'\n", "if a is not None and not b in c:\n    pass\n",
    "def outer():\n    def inner():\n        pass\n    return inner\n", "x = a +\\\n    b\n",
    "result = (a and\n          b)\n", "result = (a\n          and b)\n", "from os import *\n", "assert(x)\n",
    "def n():\n    return(1)\n", "for i in range(3): print(i)\n", "with open(f) as g: pass\n",
]
sources = st.lists(st.sampled_from(POOL), max_size=7).flatmap(
    lambda parts: st.lists(st.integers(min_value=0, max_value=3), min_size=len(parts), max_size=len(parts)).map(
        lambda gaps: "".join("\n" * g + p for g, p in zip(gaps, parts))
    )
)
option_sets = st.sampled_from([{}, {"max_line_length": 100}, {"ignore": ["E501"]}, {"ignore": ["W", "E3"]}, {"select": ["E2", "W"]}])


@settings(max_examples=500, **SLOW)
@given(sources, option_sets)
def test_the_replacement_reports_what_pep8_reports(source, options):
    lines = source.splitlines(True)
    assert new_report(lines, **options) == old_report(lines, **options)


@settings(max_examples=40, **SLOW)
@given(sources)
def test_check_files_gives_the_same_counters(source):
    with tempfile.TemporaryDirectory() as folder:
        path = os.path.join(folder, "x.py")
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(source)
        a = pep8.StyleGuide(quiet=True, config_file=False).check_files([path])
        b = pep8_replacement.StyleGuide(quiet=True, config_file=False).check_files([path])
        def summary(r):
            counters = {k: v for k, v in r.counters.items() if k not in CHANGED}
            return (r.total_errors - sum(v for k, v in r.counters.items() if k in CHANGED), counters)

        assert summary(b) == summary(a)


def test_the_replacement_keeps_the_pep8_default_ignore_list():
    assert tuple(pep8.StyleGuide(config_file=False).options.ignore) == pep8_replacement.PEP8_DEFAULT_IGNORE
    assert tuple(pep8_replacement.StyleGuide(config_file=False).options.ignore) == pep8_replacement.PEP8_DEFAULT_IGNORE
    assert tuple(pycodestyle.StyleGuide(config_file=False).options.ignore) != pep8_replacement.PEP8_DEFAULT_IGNORE


# --- known differences, pinned on both sides: if either changes, review the migration ----------------

NEW_CODE_EXAMPLES = {
    "E741": "l = 1\n",
    "E722": "try:\n    pass\nexcept:\n    pass\n",
    "W605": "a = \"\\d\"\n",
    "E305": "def f():\n    pass\nx = 1\n",
    "E306": "def f():\n    x = 1\n    def g():\n        pass\n",
    "E252": "def m(a: int=1):\n    pass\n",
}


@pytest.mark.parametrize("code,source", sorted(NEW_CODE_EXAMPLES.items()))
def test_pycodestyle_reports_codes_that_pep8_never_had(code, source):
    lines = source.splitlines(True)
    assert code in {c for _, _, c in naive_report(lines)}
    assert code not in {c for _, _, c in old_report(lines)}
    assert code not in {c for _, _, c in new_report(lines)}
    assert code in pep8_replacement.NEW_CODES


def raw_codes(module, lines):
    guide = module.StyleGuide(reporter=collector(module.BaseReport), quiet=True, config_file=False)
    module.Checker(filename="x.py", lines=lines, options=guide.options).check_all()
    return {c for _, _, c in guide.options.report.found}


def test_changed_codes_fire_on_different_patterns():
    examples = {
        "E721": "type(a) == type(b)\n",
        "E302": "# comment\n\ndef f():\n    pass\n",
        "E402": "if x:\n    pass\nimport os\n",
    }
    for code, source in examples.items():
        lines = source.splitlines(True)
        assert (code in raw_codes(pep8, lines)) != (code in raw_codes(pycodestyle, lines)), code


def test_pep8_does_not_know_async_def():
    # pep8 1.7.1 predates async syntax: it treats "async def" as an ordinary line, so the blank-line
    # checks (E301, E302, E303, E305) do not apply to it. pycodestyle applies them.
    lines = "import os\nasync def k():\n    await os\n".splitlines(True)
    assert "E302" not in raw_codes(pep8, lines)
    assert "E302" in raw_codes(pycodestyle, lines)


def test_the_python_2_checks_are_gone():
    lines = "d.has_key(1)\n".splitlines(True)
    assert "W601" in {c for _, _, c in old_report(lines)}
    assert "W601" not in {c for _, _, c in naive_report(lines)}


def test_the_naive_import_is_not_the_same_linter():
    lines = "l = 1\ntry:\n    pass\nexcept:\n    pass\n".splitlines(True)
    assert naive_report(lines) != old_report(lines)
    assert new_report(lines) == old_report(lines)
`;

function build(_ctx: RecipeContext): SeanceBundle {
  const replacement = REPLACEMENT.replace(
    '__NEW_CODES__',
    `${PEP8_NEW_CODES.map((c) => `"${c}"`).join(', ')},`,
  );
  const files: SeanceFile[] = [
    { path: `${DIR}/test_seance_pep8.py`, content: TEST, role: 'test' },
    { path: `${DIR}/pep8_replacement.py`, content: replacement, role: 'replacement' },
  ];
  const compares = [
    'The sorted list of (line, column, code) that the checker reports for generated source, and for check_files the total and per-code counters.',
    'The source is built from a pool of 40 Python 3 fragments (imports, definitions, comparisons, escapes, long lines, continuation lines) with random blank lines; options: default, longer lines, ignore lists, select lists. Both sides get the same options.',
    'Not compared: E301 to E304, E402 and E721 (they fire on different patterns now), Python 2 constructs (pycodestyle dropped W601 to W604) and async def (pep8 does not know it), the command line interface and configuration files.',
  ];
  const install = ['pip install pytest hypothesis pycodestyle'];
  const oldVersions = oldVersionsFor('pep8', depOfContext(_ctx));
  compares.push(`Versions: ${oldVersions.note}`);
  const run = 'pytest seance/pep8';
  files.push({
    path: `${DIR}/README.md`,
    role: 'readme',
    content: renderReadme({
      title: 'pep8 to pycodestyle',
      recipe: 'pep8',
      files: [
        {
          path: `${DIR}/test_seance_pep8.py`,
          what: 'the differential property test (pytest and Hypothesis)',
        },
        {
          path: `${DIR}/pep8_replacement.py`,
          what: 'StyleGuide and Checker on top of pycodestyle, with the pep8 results',
        },
      ],
      install,
      run,
      compares,
      known: PEP8_KNOWN,
      versions: oldVersions.note,
      notes: [
        'The new checks are valuable. Once the migration is done, remove codes from NEW_CODES one at a time and fix what they report.',
      ],
    }),
  });
  return makeBundle({
    language: 'python',
    recipe: 'pep8',
    title: 'pep8 to pycodestyle',
    files,
    install,
    run,
    compares,
    knownDifferences: PEP8_KNOWN,
    members: ['StyleGuide', 'Checker'],
    oldVersions,
  });
}

function mutants(): Mutant[] {
  const path = `${DIR}/pep8_replacement.py`;
  const base = build({} as RecipeContext).files.find((f) => f.path === path)?.content ?? '';
  return [
    {
      id: 'naive-rename',
      description: 'pycodestyle used directly (change the import and nothing else)',
      files: [
        {
          path,
          role: 'replacement',
          content: [
            'import pycodestyle',
            'StyleGuide = pycodestyle.StyleGuide',
            'Checker = pycodestyle.Checker',
            'BaseReport = pycodestyle.BaseReport',
            'PEP8_DEFAULT_IGNORE = ("E121", "E123", "E126", "E226", "E24", "E704")',
            'NEW_CODES = ()',
            '',
          ].join('\n'),
        },
      ],
    },
    {
      id: 'ignores-too-much',
      description: 'also ignores every E2 whitespace check',
      files: [
        {
          path,
          role: 'replacement',
          content: base.replace(
            'kwargs["ignore"] = PEP8_DEFAULT_IGNORE',
            'kwargs["ignore"] = PEP8_DEFAULT_IGNORE + ("E2",)',
          ),
        },
      ],
    },
  ];
}

export const pep8Recipe: Recipe = {
  id: 'pep8',
  language: 'python',
  ecosystem: 'pypi',
  old: 'pep8',
  successors: ['pycodestyle'],
  why: 'A rename that looks like a find-and-replace but changes the results: twelve checks were added.',
  build,
  mutants,
};
